import { RuleId, RuleViolation, AiDisclosureRuleConfig } from '../types';
import { ContentPayload } from '../../connectors/types';

const DEFAULT_DISCLOSURE_PHRASES = [
  'ai-generated',
  'generated with ai',
  'ai disclosure',
  'written with ai',
  'ai-assisted',
  'created with ai',
  'generated by ai',
];

export function evaluateAiDisclosure(
  destinationKey: string,
  content: ContentPayload,
  config: AiDisclosureRuleConfig
): RuleViolation[] {
  if (config.enabled === false) {
    return [];
  }

  const isMarkedAi = Boolean(
    content.metadata?.aiGenerated === true ||
      content.metadata?.isAiGenerated === true ||
      content.metadata?.aiAssisted === true
  );

  const requireIfAi = config.requireIfAiGenerated ?? true;
  const isDisclosureMandatory = config.required === true || (requireIfAi && isMarkedAi);

  if (!isDisclosureMandatory) {
    return [];
  }

  const fullText = [content.title, content.summary ?? '', content.body].join(' ').toLowerCase();
  const phrases = config.disclaimerPhrases && config.disclaimerPhrases.length > 0
    ? config.disclaimerPhrases
    : DEFAULT_DISCLOSURE_PHRASES;

  // Check 1: disclaimer phrase present in text
  const hasDisclaimerPhrase = phrases.some((phrase) =>
    fullText.includes(phrase.toLowerCase().trim())
  );

  // Check 2: required tag present
  let hasRequiredTag = false;
  if (config.requiredTag && content.tags && content.tags.length > 0) {
    const targetTag = config.requiredTag.toLowerCase().trim();
    hasRequiredTag = content.tags.some((t) => t.toLowerCase().trim() === targetTag);
  }

  if (!hasDisclaimerPhrase && !hasRequiredTag) {
    return [
      {
        ruleId: RuleId.AI_DISCLOSURE,
        message: `AI disclosure missing for destination '${destinationKey}': content is identified as AI-assisted or destination mandates disclosure, but no disclosure phrase or required tag was found.`,
        details: {
          destinationKey,
          isMarkedAi,
          requiredPhrases: phrases,
          requiredTag: config.requiredTag,
        },
      },
    ];
  }

  return [];
}
